(() => {
'use strict';
const W=8,H=6, SAVE='first-world-v1';
const tileTypes=['forest','grass','berry','grass','rock','grass','forest','grass','grass','water','grass','berry','grass','grass','forest','grass','berry','water','rock','grass','forest','rock','grass','berry','grass','water','grass','forest','grass','grass','berry','grass','forest','grass','grass','grass','rock','grass','forest','grass','grass','berry','forest','grass','grass','water','grass','berry'];
const geneNames=['curiosity','empathy','caution','stamina','sociability','resilience','patience','creativity','awareness','generosity','adaptability','boldness'];
const firstNames=['Ari','Nia','Sol','Mira','Ilan','Tala','Oren','Luma','Rin','Koa','Asha','Vale','Noa','Sera','Elio','Uma'];
const $=s=>document.querySelector(s); const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, timer=null, speed=1, selected=null, filter='all', activeTab='life';
function rng(){state.seed=(Math.imul(1664525,state.seed)+1013904223)>>>0;return state.seed/4294967296}
function pick(a){return a[Math.floor(rng()*a.length)]}
function clamp(n,a=0,b=100){return Math.max(a,Math.min(b,n))}
function makeTiles(){return tileTypes.map((type,i)=>({type,food:type==='berry'?5:type==='forest'?2:0,water:type==='water'?12:0,wood:type==='forest'?8:0,stone:type==='rock'?8:0,fibre:type==='forest'?6:type==='grass'?4:0,i}))}
function makeAgent(name,id,x,y,genes,age=20,gen=0,parents=[]){if(Array.isArray(genes))genes=Object.fromEntries(geneNames.map((k,i)=>[k,genes[i]]));return{id,name,x,y,genes,age,gen,parents,alive:true,health:90,food:7,water:7,energy:75,likes:{},knowledge:[],observed:[],seenTiles:[],supplies:{wood:0,stone:0,fibre:0},project:null,lastAction:'Looking around',born:state.day,death:null}}
function fresh(){state={version:2,seed:Math.floor(Math.random()*4294967295),day:1,weather:'clear',tiles:makeTiles(),agents:[],events:[],tech:{nodes:[],trials:[]},nextId:3,observer:[]};let a=makeAgent('Adam',1,0,2,[55,61,50,62,58,57,54,52,56,57,58,51]);let e=makeAgent('Eve',2,1,2,[62,67,54,57,63,56,61,62,59,61,58,55]);a.likes[2]=50;e.likes[1]=50;state.agents=[a,e];event('world','Adam and Eve wake beneath an open sky. Neither knows this place yet.');event('speech','Adam','There is light here. I can see trees, but I do not know what they offer.');event('speech','Eve','Then let us look. We can learn what keeps us here.');save()}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state))}catch(e){}}
function load(){try{let x=JSON.parse(localStorage.getItem(SAVE));if(x&&[1,2].includes(x.version)&&x.tiles?.length===48&&x.agents?.length){state=x;TechReferee.ensure(state);return}}catch(e){}fresh()}
function event(type,a,b){let x={day:state.day,type,who:type==='speech'||type==='observer'?a:null,text:type==='speech'||type==='observer'?b:a};state.events.push(x);if(state.events.length>700)state.events.shift()}
function tile(x,y){return state.tiles[y*W+x]}
function living(){return state.agents.filter(a=>a.alive)}
function peopleNear(a){return living().filter(b=>b.id!==a.id&&Math.abs(a.x-b.x)+Math.abs(a.y-b.y)<=2)}
function moveToward(a,test){let options=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=tile(x,y);if(test(t)){let d=Math.abs(x-a.x)+Math.abs(y-a.y);options.push({x,y,d,t})}}options.sort((u,v)=>u.d-v.d||rng()-.5);if(!options.length)return false;let goal=options[0];if(goal.d===0)return true;if(goal.x!==a.x)a.x+=Math.sign(goal.x-a.x);else a.y+=Math.sign(goal.y-a.y);return false}
function observe(a){let t=tile(a.x,a.y);let pos=a.y*W+a.x;if(!a.seenTiles.includes(pos))a.seenTiles.push(pos);if(!a.observed.includes(t.type)){a.observed.push(t.type);let nouns={forest:'trees and fallen branches',grass:'soft ground and scattered leaves',berry:'small red fruit',water:'moving water',rock:'loose hard stones'};event('observation',`${a.name} notices ${nouns[t.type]} for the first time.`)}a.lastAction='Observing the '+t.type}
function speak(a,text){event('speech',a.name,text);for(let b of peopleNear(a)){if(a.id===b.id)continue;b.likes[a.id]=clamp((b.likes[a.id]??45)+3);a.likes[b.id]=clamp((a.likes[b.id]??45)+3);for(let k of a.knowledge)if(!b.knowledge.includes(k)){b.knowledge.push(k);let name=TechReferee.get(state,k)?.name||'a discovery';event('observation',`${b.name} learns about ${name.toLowerCase()} from ${a.name}.`)}}}
function experiment(a,c){let result=TechReferee.tryExperiment(a,state,c,rng);if(result.status==='learned'){a.project=null;a.lastAction='Discovering '+result.node.name;event('discovery',`${a.name} ${result.newToWorld?'discovers':'rediscovers'} ${result.node.name.toLowerCase()}. ${result.node.detail}`);speak(a,`I tried ${c.materials.join(' with ')} and learned ${result.node.name.toLowerCase()}. ${result.node.detail}`)}else if(result.status==='failed'){a.lastAction='Experimenting with '+c.materials.join(' and ');if(rng()<.45)event('experiment',`${a.name} tries to ${c.method} ${c.materials.join(' and ')}, but it does not work yet.`)}return result}
function exploreTech(a,t){let options=TechReferee.possibilities(a,state);if(!options.length){a.project=null;return false}let c=options.find(c=>c.id===a.project)||TechReferee.choose(a,state,rng);if(!c)return false;a.project=c.id;let missing=TechReferee.missing(a,c);if(missing==='food'||missing==='water')return false;if(missing){if(t[missing]>0){t[missing]--;a.supplies[missing]=Math.min(9,(a.supplies[missing]||0)+1);a.lastAction='Gathering '+missing+' for an experiment'}else{moveToward(a,t=>t[missing]>0);a.lastAction='Seeking '+missing+' for an experiment'}return true}if(t.type!==c.site){moveToward(a,t=>t.type===c.site);a.lastAction='Finding a place to experiment';return true}experiment(a,c);return true}
function wander(a){let choices=[];for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let x=a.x+dx,y=a.y+dy;if(x>=0&&x<W&&y>=0&&y<H)choices.push({x,y,seen:a.seenTiles.includes(y*W+x)})}let fresh=choices.filter(p=>!p.seen),next=pick(fresh.length?fresh:choices);if(!next)return false;a.x=next.x;a.y=next.y;a.lastAction='Exploring unfamiliar ground';return true}
function action(a){if(!a.alive)return;let t=tile(a.x,a.y);observe(a);let nearby=peopleNear(a);let lowWater=a.water<3,lowFood=a.food<3;
if(lowWater){if(t.water>0){t.water--;a.water=Math.min(TechReferee.knows(a,state,'water-store')?12:10,a.water+(TechReferee.knows(a,state,'water-store')?8:6));if(TechReferee.knows(a,state,'safe-water'))a.health=clamp(a.health+2);a.lastAction='Drinking';if(rng()<.42)speak(a,'This water takes away the thirst. I will remember where it is.')}else{moveToward(a,t=>t.water>0);a.lastAction='Searching for water'}return}
if(lowFood){if(t.food>0){t.food--;a.food=Math.min(10,a.food+(TechReferee.knows(a,state,'food')?6:5)+(TechReferee.knows(a,state,'tool')?1:0));a.lastAction='Gathering food';if(t.type==='berry'&&!TechReferee.knows(a,state,'food')){let c=TechReferee.possibilities(a,state).find(c=>c.effect==='food');if(c)experiment(a,c)}else if(rng()<.3)speak(a,'I found food here. There may be more tomorrow.')}else{moveToward(a,t=>t.food>0);a.lastAction='Searching for food'}return}
if(a.energy<35){a.energy=clamp(a.energy+42);a.lastAction='Resting';return}
if(a.food>=5&&a.water>=5&&a.energy>=40&&rng()<.38&&exploreTech(a,t))return;
if(a.food>=6&&a.water>=6&&a.energy>=45&&rng()<.16&&wander(a))return;
if(nearby.length&&rng()<.5){let b=pick(nearby);let shared=a.knowledge.find(k=>!b.knowledge.includes(k));if(shared){let d=TechReferee.get(state,shared);speak(a,`${b.name}, come here. I found ${d?.name.toLowerCase()||'something useful'}.`)}else if(a.food>=5&&b.food<3){a.food--;b.food++;a.likes[b.id]=clamp((a.likes[b.id]??45)+3);b.likes[a.id]=clamp((b.likes[a.id]??45)+5);speak(a,`Take some of what I found, ${b.name}. We can search again together.`)}else{let lines=[`The ${t.type==='water'?'water':t.type==='forest'?'trees':'ground'} feels different today. Have you noticed?`,`I wonder which places hold food after the weather changes.`,`I am glad to see you, ${b.name}. Let us keep looking.`,`Yesterday taught me little. Perhaps today will teach us more.`];speak(a,pick(lines))}a.lastAction='Speaking with '+b.name;return}
if(t.food>0&&a.food<8){t.food--;a.food+=2;a.lastAction='Storing food';return}if(t.water>0&&a.water<8){t.water--;a.water+=2;a.lastAction='Storing water';return}
let goal=pick(['food','water','wood','stone']);moveToward(a,t=>t[goal]>0);a.lastAction='Exploring';if(rng()<.27)speak(a,pick(['I have not seen this ground before.','There may be something useful beyond these trees.','I am going to look further.']))}
function inherit(p,q){let child={};let order=[...geneNames].sort(()=>rng()-.5);let fromFirst=new Set(order.slice(0,geneNames.length/2));for(let k of geneNames){let source=fromFirst.has(k)?p:q;let v=source.genes[k];if(rng()<.08)v=clamp(v+(rng()<.5?-1:1)*(4+Math.floor(rng()*15)));child[k]=v}return child}
function birth(){let adults=living().filter(a=>a.age>=18&&a.food>=5&&a.water>=4&&a.health>=55);if(living().length>=18)return;for(let i=0;i<adults.length;i++)for(let j=i+1;j<adults.length;j++){let a=adults[i],b=adults[j];if(Math.abs(a.x-b.x)+Math.abs(a.y-b.y)>2)continue;if(a.parents.includes(b.id)||b.parents.includes(a.id)||a.parents.some(id=>b.parents.includes(id)))continue;if((a.likes[b.id]??0)<68||(b.likes[a.id]??0)<68)continue;if(state.day-Math.max(a.born,b.born)<3)continue;if(rng()>.18)continue;let id=state.nextId++,name=firstNames[(id-3)%firstNames.length];let c=makeAgent(name,id,a.x,a.y,inherit(a,b),0,Math.max(a.gen,b.gen)+1,[a.id,b.id]);c.food=3;c.water=3;c.health=76;c.energy=70;a.food-=2;b.food-=2;a.water--;b.water--;a.likes[id]=75;b.likes[id]=75;c.likes[a.id]=75;c.likes[b.id]=75;state.agents.push(c);event('birth',`${name} is born to ${a.name} and ${b.name}. Their traits blend, with mutation possible in each trait.`);speak(a,`${b.name}, ${name} is here. We must keep enough for all of us.`);return}}
function upkeep(a){a.age++;a.food=Math.max(0,a.food-((TechReferee.knows(a,state,'stored-food')||TechReferee.knows(a,state,'prepared-food'))&&state.day%3===0?0:1));a.water=Math.max(0,a.water-1);a.energy=clamp(a.energy-5);if(a.food===0)a.health-=7;if(a.water===0)a.health-=9;if(a.energy<15)a.health-=2;if(state.weather==='rain'&&!TechReferee.knows(a,state,'strong-shelter'))a.health-=TechReferee.knows(a,state,'shelter')||TechReferee.knows(a,state,'fire')?1:3;if(a.food>1&&a.water>1&&a.energy>30)a.health=clamp(a.health+3);if(a.health<=0){a.health=0;a.alive=false;a.death=state.day;event('death',`${a.name} dies after the world runs short of what they need.`)}}
function grow(){for(let t of state.tiles){if(t.type==='berry')t.food=Math.min(5,t.food+(rng()<.56?1:0));if(t.type==='forest'){t.food=Math.min(3,t.food+(rng()<.25?1:0));t.wood=Math.min(8,t.wood+(rng()<.3?1:0))}if(t.type==='water')t.water=Math.min(12,t.water+(rng()<.83?2:0));if(t.type==='grass'||t.type==='forest')t.fibre=Math.min(t.type==='forest'?6:4,t.fibre+(rng()<.36?1:0))}state.weather=rng()<.17?'rain':rng()<.13?'wind':'clear'}
function day(){state.day++;grow();let agents=[...living()];for(let a of agents){upkeep(a);if(a.alive){action(a);action(a)}}birth();if(state.day%5===0)event('world',`The ${season()} continues. ${living().length} ${living().length===1?'person remains':'people remain'} in the clearing.`);save();render()}
function season(){return ['early spring','late spring','summer','autumn'][Math.floor((state.day-1)/14)%4]}
function weatherName(){return state.weather==='clear'?'CLEAR SKIES':state.weather==='rain'?'PASSING RAIN':'COOL WIND'}
function renderMap(){let target=$('#world-map');target.innerHTML=state.tiles.map((t,i)=>`<div class="tile ${t.type}" data-tile="${i}" title="${t.type} · ${t.food||t.water||t.wood||t.stone} available"></div>`).join('');for(let a of living()){let el=document.createElement('button');el.type='button';el.className='agent-marker '+(a.id===1?'adam':a.id===2?'eve':'child');el.style.left=`${(a.x+.5)/W*100}%`;el.style.top=`${(a.y+.5)/H*100}%`;el.textContent=a.name[0];el.title=a.name+' · '+a.lastAction;el.setAttribute('aria-label','Inspect '+a.name);el.onclick=()=>openAgent(a.id);target.append(el)}}
function renderFeed(){let arr=filter==='all'?state.events:state.events.filter(e=>e.type===filter);$('#activity-feed').innerHTML=arr.slice(-30).reverse().map(e=>`<div class="event ${e.type}"><div class="event-time">D${String(e.day).padStart(2,'0')}</div><div class="event-body"><div class="event-type">${e.type==='speech'?'● CONVERSATION':e.type==='observer'?'◌ OBSERVER TALK':e.type.toUpperCase()}</div><p>${e.type==='speech'||e.type==='observer'?`<strong>${esc(e.who)}</strong> <q>${esc(e.text)}</q>`:esc(e.text)}</p></div></div>`).join('');$('#event-count').textContent=state.events.length+' EVENTS';$('#filter-btn').innerHTML=(filter==='all'?'ALL EVENTS':filter.toUpperCase())+' <span>⌄</span>'}
function renderPeople(){let persons=[...living(),...state.agents.filter(a=>!a.alive)].slice(0,16);$('#people-list').innerHTML=persons.map(a=>`<div class="person-row" role="button" tabindex="0" data-person="${a.id}"><div class="avatar ${a.id===2?'eve':a.id>2?'child':''}">${esc(a.name[0])}</div><div><div class="person-name">${esc(a.name)}</div><div class="person-meta">GEN ${String(a.gen).padStart(2,'0')} · AGE ${a.age} DAYS ${a.alive?'':'· DIED D'+a.death}</div></div><div class="person-state ${a.health<50?'weak':''}">${a.alive?esc(a.lastAction.toUpperCase()):'REMEMBERED'}</div><div class="person-chevron">›</div></div>`).join('');document.querySelectorAll('[data-person]').forEach(el=>{el.onclick=()=>openAgent(Number(el.dataset.person));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openAgent(Number(el.dataset.person))}}});$('#people-count').textContent=String(living().length).padStart(2,'0')}
function render(){let alive=living();$('#day-count').textContent=String(state.day).padStart(2,'0');$('#population-count').textContent=String(alive.length).padStart(2,'0')+' LIVING';$('#season-name').textContent=season().toUpperCase();$('#weather-label').textContent=weatherName();$('#elapsed-label').textContent=`DAY ${String(state.day).padStart(2,'0')} · ${weatherName()}`;$('#map-condition').textContent=state.weather.toUpperCase();$('#world-status').textContent=timer?'SIMULATION RUNNING':'SIMULATION PAUSED';$('#map-caption').textContent=alive.length?`${alive.map(a=>a.name).slice(0,3).join(', ')}${alive.length>3?' and others':''} move through the clearing.`:'The clearing is silent. Start a new world from About.';let totals={food:0,water:0,wood:0,stone:0,fibre:0};for(let t of state.tiles)for(let k in totals)totals[k]+=t[k];for(let k in totals)$('#total-'+k).textContent=totals[k];$('#tech-count').textContent=`${state.tech.nodes.length} EMERGED`;$('#tech-list').innerHTML=state.tech.nodes.length?state.tech.nodes.slice(-8).map(d=>`<span class="tech-chip" title="${esc(d.detail)}">✳ ${esc(d.name.toUpperCase())}</span>`).join(''):'<span class="tech-empty">No technology has emerged yet.</span>'; renderMap();renderFeed();renderPeople();if(selected)renderDrawer();$('#play-label').textContent=timer?'PAUSE WORLD':'START WORLD';$('#play-icon').textContent=timer?'Ⅱ':'▶'}
function meter(label,v){return `<div class="meter-row"><span>${label}</span><div class="meter ${v<35?'low':''}"><i style="width:${clamp(v)}%"></i></div><span>${Math.round(v)}</span></div>`}
function renderDrawer(){let a=state.agents.find(p=>p.id===selected);if(!a)return;let peers=state.agents.filter(b=>b.id!==a.id&&b.alive);let intro=`${a.alive?'Living':'Remembered'} · Generation ${a.gen} · ${a.age} days old`;let content=`<div class="kicker">PERSON / ${String(a.id).padStart(3,'0')}</div><h2>${esc(a.name)}</h2><p class="drawer-intro">${intro}. ${a.alive?esc(a.lastAction)+'.':'Their story ended on day '+a.death+'.'}</p><div class="drawer-tabs"><button class="drawer-tab ${activeTab==='life'?'active':''}" data-tab="life">LIFE</button><button class="drawer-tab ${activeTab==='mind'?'active':''}" data-tab="mind">MIND & GENES</button><button class="drawer-tab ${activeTab==='talk'?'active':''}" data-tab="talk">SPEAK TO THEM</button></div>`;
if(activeTab==='life')content+=`<div class="drawer-section"><h3>CURRENT CONDITION</h3>${meter('HEALTH',a.health)}${meter('ENERGY',a.energy)}${meter('FOOD',a.food*10)}${meter('WATER',a.water*10)}</div><div class="drawer-section"><h3>CARRIED MATERIALS</h3><div class="fact-row"><span>Wood</span><span>${a.supplies.wood}</span></div><div class="fact-row"><span>Stone</span><span>${a.supplies.stone}</span></div><div class="fact-row"><span>Fibre</span><span>${a.supplies.fibre}</span></div></div><div class="drawer-section"><h3>CONNECTIONS</h3>${peers.length?peers.map(b=>`<div class="fact-row"><span>${esc(b.name)}</span><span>AFFINITY ${Math.round(a.likes[b.id]??0)} / 100</span></div>`).join(''):'<p class="drawer-intro">No one else remains.</p>'}</div><div class="drawer-section"><h3>FAMILY</h3><div class="fact-row"><span>Parents</span><span>${a.parents.length?a.parents.map(id=>esc(state.agents.find(p=>p.id===id)?.name||'?')).join(' & '):'Founding generation'}</span></div><div class="fact-row"><span>Children</span><span>${state.agents.filter(p=>p.parents.includes(a.id)).map(p=>esc(p.name)).join(', ')||'None yet'}</span></div></div>`;
if(activeTab==='mind')content+=`<div class="drawer-section"><h3>LEARNED IN THIS WORLD</h3>${a.knowledge.length?a.knowledge.map(k=>`<div class="fact-row"><span>${esc(TechReferee.get(state,k)?.name||'Unknown')}</span><span>KNOWN</span></div>`).join(''):'<p class="drawer-intro">No discoveries yet. Knowledge arrives through observation, experiments, or speech.</p>'}</div><div class="drawer-section"><h3>INHERITED TRAITS</h3>${geneNames.map(k=>meter(k.toUpperCase(),a.genes[k])).join('')}<p class="drawer-intro" style="margin-top:16px">Each trait is inherited from one parent with an independent 8% chance of mutation. This character has no knowledge from outside the clearing.</p></div>`;
if(activeTab==='talk')content+=`<div class="drawer-section"><h3>OBSERVER CHANNEL</h3><p class="talk-prompt">Ask ${esc(a.name)} about what they have experienced here. Your exchange enters the observer record, but it does not enter their memory or change their decisions.</p><form id="talk-form" class="talk-form"><input id="talk-input" maxlength="180" placeholder="Ask about this world…" aria-label="Message to ${esc(a.name)}" required><button type="submit">SEND ↗</button></form><div id="talk-reply"></div></div>`;
$('#drawer-content').innerHTML=content;document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{activeTab=el.dataset.tab;renderDrawer()});let form=$('#talk-form');if(form)form.onsubmit=e=>{e.preventDefault();let input=$('#talk-input');let q=input.value.trim();if(!q)return;let reply=observerReply(a,q);event('observer','You → '+a.name,q);event('observer',a.name+' → You',reply);save();renderFeed();$('#talk-reply').innerHTML=`<div class="reply">“${esc(reply)}”<small>OBSERVER EXCHANGE · NOT STORED IN ${esc(a.name.toUpperCase())}'S MEMORY</small></div>`;input.value=''}}
function observerReply(a,q){let s=q.toLowerCase(),t=tile(a.x,a.y);if(!a.alive)return 'I have no answer now.';if(/food|eat|hungry|berry/.test(s))return a.knowledge.includes('berries')?'I have found that the red fruit can ease hunger. I look for more when food is low.':'I am still learning what can be eaten here.';if(/water|drink|thirst/.test(s))return t.type==='water'?'The moving water is here. I drink when I need it.':'I seek the moving water when I am thirsty.';if(/adam|eve|like|friend|love|other|people/.test(s)){let b=living().find(b=>b.id!==a.id);return b?`${b.name} is here too. We have spoken, and I know more when we look together.`:'I cannot see anyone else nearby.'}if(/know|learn|discover|fire|shelter|stone/.test(s))return a.knowledge.length?`I know of ${a.knowledge.map(k=>TechReferee.get(state,k)?.name.toLowerCase()||'something useful').join(' and ')}. I learned it here.`:'I know very little yet. I can only tell you what I find.';if(/how|feel|alive|health|survive/.test(s))return `I feel ${a.health<40?'weak':'steady'}. I have ${a.food} food and ${a.water} water with me. I must keep searching.`;return `I hear you. Here I can see ${t.type==='berry'?'red fruit':t.type==='forest'?'trees':t.type==='water'?'moving water':t.type==='rock'?'stones':'open ground'}. I will learn what it means by being here.`}
function openAgent(id){selected=id;activeTab='life';$('#drawer-overlay').classList.remove('hidden');$('#detail-drawer').classList.remove('hidden');renderDrawer()}
function closeDrawer(){selected=null;$('#drawer-overlay').classList.add('hidden');$('#detail-drawer').classList.add('hidden')}
function modal(html){$('#modal-content').innerHTML=html;$('#modal-overlay').classList.remove('hidden')}
function about(){modal(`<div class="kicker">ABOUT THE EXPERIMENT</div><h2>A world with no win state.</h2><p>Adam and Eve begin with no map, recipes, or outside facts. They observe their surroundings, gather resources, and share discoveries by speaking. Their needs, relationships, and decisions create a record you can inspect.</p><div class="modal-grid"><div><strong>INHERITANCE</strong><span>Six traits come from each parent, with an 8% chance of mutation per trait. Both parents must feel close and have enough supplies for a birth.</span></div><div><strong>KNOWLEDGE</strong><span>A hidden referee evaluates experiments with observed materials. New inventions appear as a dependency graph shaped by what people actually discover and share.</span></div><div><strong>OBSERVER CHANNEL</strong><span>Speak to a person from their profile. Your exchange is recorded for you, but never added to their knowledge or decision memory.</span></div><div><strong>THIS VERSION</strong><span>The minds here use local simulation rules and grounded dialogue. Live ChatGPT model calls require a connected server API, which this version does not have.</span></div></div><button id="reset-btn" class="outline-button" style="background:#23412d;border:0;margin-top:23px">BEGIN A NEW WORLD</button>`);$('#reset-btn').onclick=()=>{if(timer)pause();fresh();closeDrawer();$('#modal-overlay').classList.add('hidden');render()}}
function lineage(){let gens=[...new Set(state.agents.map(a=>a.gen))].sort((a,b)=>a-b);modal(`<div class="kicker">THE FAMILY RECORD</div><h2>Lineage</h2><p>Every new person inherits six character traits from each parent. Each trait can change through an 8% mutation chance.</p><div class="lineage-tree">${gens.map(g=>`<div class="lineage-gen"><div class="lineage-label">GENERATION ${String(g).padStart(2,'0')}</div><div class="lineage-members">${state.agents.filter(a=>a.gen===g).map(a=>`<div class="lineage-node">${esc(a.name)}${a.alive?'':' †'}<small>${a.parents.length?'FROM '+a.parents.map(id=>esc(state.agents.find(p=>p.id===id)?.name||'?')).join(' + '):'FOUNDER'}</small></div>`).join('')}</div></div>`).join('')}</div>`)}
function techTree(){let nodes=state.tech.nodes, depth=id=>{let n=TechReferee.get(state,id);return n?.parents?.length?1+Math.max(...n.parents.map(depth)):0},levels=[...new Set(nodes.map(n=>depth(n.id)))].sort((a,b)=>a-b);modal(`<div class="kicker">THE HIDDEN REFEREE'S RECORD</div><h2>Emergent technology</h2><p>No full tree is shown in advance. People test materials they have observed and carry. A successful experiment becomes a node; later inventions can depend on it. These are the paths this world has actually taken.</p><div class="tech-graph">${nodes.length?levels.map(level=>`<div class="tech-level"><div class="lineage-label">${level===0?'FIRST EXPERIMENTS':'DEPENDENCY DEPTH '+level}</div><div class="tech-nodes">${nodes.filter(n=>depth(n.id)===level).map(n=>`<div class="tech-node"><span>DAY ${String(n.day).padStart(2,'0')} · ${esc(n.discoverer)}</span><strong>${esc(n.name)}</strong><p>${esc(n.detail)}</p><small>${n.parents.length?'BUILT FROM '+n.parents.map(id=>esc(TechReferee.get(state,id)?.name||'an earlier finding')).join(' + '):'TESTED '+n.materials.map(esc).join(' + ')}</small></div>`).join('')}</div></div>`).join(''):'<p class="tech-empty">No successful experiments yet. Let the world run to see its first branch.</p>'}</div><div class="trial-record"><div class="lineage-label">RECENT EXPERIMENTS</div>${state.tech.trials.slice(-8).reverse().map(t=>`<div class="fact-row"><span>Day ${t.day} · ${esc(t.person)} tried ${esc(t.method)} (${t.materials.map(esc).join(', ')})</span><span>${t.result.toUpperCase()}</span></div>`).join('')||'<p class="tech-empty">The inhabitants have not experimented yet.</p>'}</div>`)}
function pause(){clearInterval(timer);timer=null;render()}
function play(){if(timer){pause();return}timer=setInterval(day,Math.max(110,1200/speed));render()}
load();render();$('#play-btn').onclick=play;$('#step-btn').onclick=day;document.querySelectorAll('.speed').forEach(el=>el.onclick=()=>{speed=Number(el.dataset.speed);document.querySelectorAll('.speed').forEach(x=>x.classList.toggle('active',x===el));if(timer){clearInterval(timer);timer=setInterval(day,Math.max(110,1200/speed))}});$('#about-btn').onclick=about;$('#lineage-btn').onclick=lineage;$('#tech-tree-btn').onclick=techTree;$('#filter-btn').onclick=()=>{let choices=['all','speech','discovery','birth','death','observation','observer','experiment','world'];filter=choices[(choices.indexOf(filter)+1)%choices.length];renderFeed()};$('#export-btn').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`first-world-day-${String(state.day).padStart(3,'0')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)};$('#close-drawer').onclick=closeDrawer;$('#drawer-overlay').onclick=closeDrawer;$('#close-modal').onclick=()=>$('#modal-overlay').classList.add('hidden');$('#modal-overlay').onclick=e=>{if(e.target===$('#modal-overlay'))$('#modal-overlay').classList.add('hidden')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();$('#modal-overlay').classList.add('hidden')}});
})();
